package com.aircontrol;

import android.content.Context;
import android.content.Intent;
import android.content.SharedPreferences;
import android.provider.Settings;
import android.speech.tts.TextToSpeech;
import android.util.Log;

import java.util.Locale;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/** NOVA interaction gateway: deterministic local skills first, then the central AI Brain. */
public final class NovaAssistant {
    public interface Listener { void onStatus(String text); }
    private static final String TAG="NovaAssistant"; private static final String PREFS="nova_ai_settings"; private static final String ENDPOINT="endpoint"; private static final String MODEL="model"; private static final String WAKE_PHRASE="hey nova";
    private final Context context; private final Listener listener; private final SharedPreferences prefs; private final NovaMemory memory; private final NovaSecureStore secureStore; private final NovaWebTool web=new NovaWebTool(); private final NovaSkillRegistry skills; private final NovaAppCatalog apps; private final NovaActionEngine actions; private final NovaBrain brain; private final NovaTaskManager taskManager; private final NovaAiClient aiProbe=new NovaAiClient(); private final ExecutorService probeExecutor=Executors.newSingleThreadExecutor(); private TextToSpeech tts;
    public NovaAssistant(Context context,Listener listener){this.context=context.getApplicationContext();this.listener=listener;prefs=this.context.getSharedPreferences(PREFS,Context.MODE_PRIVATE);memory=new NovaMemory(this.context);secureStore=new NovaSecureStore(this.context);apps=new NovaAppCatalog(this.context);actions=new NovaActionEngine(this.context,new NovaActionEngine.Callback(){public void status(String text){NovaAssistant.this.status(text);}public void reply(String text){NovaAssistant.this.say(text);}});brain=new NovaBrain(this.context,actions,memory,new NovaBrain.Listener(){public void onStatus(String text){NovaAssistant.this.status(text);}public void onReply(String text){NovaAssistant.this.say(text);}});taskManager=new NovaTaskManager(this.context,brain);skills=new NovaSkillRegistry(this.context,new NovaSkillRegistry.Callback(){public void reply(String text){NovaAssistant.this.say(text);}public void status(String text){NovaAssistant.this.status(text);}});tts=new TextToSpeech(this.context,result->{if(result==TextToSpeech.SUCCESS)try{tts.setLanguage(Locale.getDefault());}catch(Exception ignored){}});}
    public void saveAiSettings(String endpoint,String apiKey,String model){String cleanEndpoint=endpoint==null?"":endpoint.trim();String cleanModel=model==null?"":model.trim();if(cleanModel.isEmpty())cleanModel=isOllamaEndpoint(cleanEndpoint)?"qwen2.5:1.5b":"gpt-4o-mini";prefs.edit().putString(ENDPOINT,cleanEndpoint).putString(MODEL,cleanModel).apply();secureStore.putApiKey(apiKey==null?"":apiKey.trim());status("AI CORE CONFIGURED • "+(isOllamaEndpoint(cleanEndpoint)?"OLLAMA / ":"PROVIDER / ")+cleanModel);}
    public String getEndpoint(){return prefs.getString(ENDPOINT,"");} public String getModel(){String model=prefs.getString(MODEL,"");if(model==null||model.trim().isEmpty())return isOllamaEndpoint(getEndpoint())?"qwen2.5:1.5b":"gpt-4o-mini";return model;} public boolean hasAiCore(){return !getEndpoint().trim().isEmpty();}
    public void testAiCore(){final String endpoint=getEndpoint(),apiKey=secureStore.getApiKey(),model=getModel();if(endpoint.trim().isEmpty()){status("AI CORE • NOT CONFIGURED");say("AI Core is not configured yet.");return;}status("AI CORE • TESTING • "+aiProbe.providerId(endpoint)+" / "+model);probeExecutor.execute(()->{try{NovaProviderHealth.Result result=aiProbe.healthCheck(endpoint,apiKey,model);NovaDiagnostics.event("provider_health_test",result.state.name().toLowerCase(Locale.ROOT)+" http="+result.httpCode);String detail=result.detail==null||result.detail.isEmpty()?"":" • "+result.detail;if(result.isHealthy()){status("AI CORE • REACHABLE • "+aiProbe.providerId(endpoint));say("AI Core is reachable. "+aiProbe.providerId(endpoint)+" is responding in "+result.latencyMillis+" milliseconds. Model: "+model+".");}else{status("AI CORE • "+result.state.name().replace('_',' '));say("AI Core test failed: "+result.state.name().replace('_',' ')+" (HTTP "+result.httpCode+", "+result.latencyMillis+" milliseconds)"+detail+".");}}catch(Exception e){Log.e(TAG,"AI CORE HEALTH TEST FAILED",e);status("AI CORE • TEST ERROR");say("AI Core health test failed unexpectedly. Check the configured endpoint and network connection.");}});}
    private boolean isOllamaEndpoint(String endpoint){String e=endpoint==null?"":endpoint.trim().toLowerCase(Locale.ROOT);return !e.isEmpty()&&!e.contains("/v1")&&(e.contains(":11434")||e.contains("ollama"));}
    public void handleVoice(String raw){if(raw==null)return;String text=NovaInputNormalizer.normalize(raw),lower=text.toLowerCase(Locale.ROOT);int wake=lower.indexOf(WAKE_PHRASE);if(wake>=0){text=text.substring(wake+WAKE_PHRASE.length()).trim();if(text.isEmpty()){say("Yes. I am listening.");return;}}else if(lower.equals("nova")){say("Yes. I am listening.");return;}handle(text);}
    public void handle(String raw){if(raw==null)return;String command=NovaInputNormalizer.normalize(raw);if(command.isEmpty())return;String c=command.toLowerCase(Locale.ROOT);status("PROCESSING • "+command);try{if(containsAny(c,"stop nova","stop listening","be quiet","stop speaking")){if(tts!=null)tts.stop();taskManager.cancelAll();say("Okay. I stopped NOVA's active and queued tasks.");return;}if(containsAny(c,"task status","show tasks","list tasks","what tasks are running","task list")){say(taskManager.statusText());return;}if(containsAny(c,"active task","what are you doing","what task are you running")){say(taskManager.activeText());return;}if(containsAny(c,"cancel queued tasks","cancel queued goals")){int count=taskManager.cancelQueued();say(count==0?"There are no queued tasks to cancel.":"Cancelled "+count+" queued task"+(count==1?".":"s."));return;}if(c.equals("cancel tasks")||c.equals("cancel all tasks")||c.equals("cancel all")){taskManager.cancelAll();say("All NOVA tasks have been cancelled.");return;}if(skills.handle(command))return;if(handleMemory(c,command))return;if(containsAny(c,"go home","home screen","take me home")){executeLocal("home","Going home.");return;}if(containsAny(c,"go back","back")){executeLocal("back","Going back.");return;}if(containsAny(c,"recent apps","open recents","show recents")){executeLocal("recents","Opening recent apps.");return;}if(containsAny(c,"notifications","show notifications")){executeLocal("notifications","Opening notifications.");return;}if(containsAny(c,"quick settings","open quick settings")){executeLocal("quick_settings","Opening quick settings.");return;}if(containsAny(c,"scroll up","swipe up")){executeLocal("scroll_up","Scrolling up.");return;}if(containsAny(c,"scroll down","swipe down")){executeLocal("scroll_down","Scrolling down.");return;}if(containsAny(c,"swipe left","go left")){executeLocal("swipe_left","Moving left.");return;}if(containsAny(c,"swipe right","go right")){executeLocal("swipe_right","Moving right.");return;}if(containsAny(c,"read screen","what is on screen","describe screen","what can you see")){say(readScreen());return;}if(containsAny(c,"show ui snapshot","inspect screen","understand screen")){say(getUiSnapshot());return;}if(containsAny(c,"recent notifications","read notifications","what notifications do i have")){say(NovaNotificationListenerService.snapshot());return;}if(containsAny(c,"open settings","settings")){executeLocal("settings","Opening settings.");return;}if(containsAny(c,"open accessibility settings","accessibility settings")){launch(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS));say("Opening accessibility settings.");return;}if(containsAny(c,"open notification access","notification access")){launch(new Intent("android.settings.ACTION_NOTIFICATION_LISTENER_SETTINGS"));say("Opening notification access settings.");return;}if(containsAny(c,"list apps","show my apps","what apps do i have")){say(apps.launchableSummary(35));return;}if(c.startsWith("search for ")||c.startsWith("search ")||c.startsWith("google ")){String q=command.replaceFirst("(?i)^(search for|search|google)\\s+","").trim();if(!q.isEmpty()){search(q);return;}}java.util.regex.Matcher numbered=java.util.regex.Pattern.compile("(?i)(?:tap|click|open)\\s+(?:the\\s+)?(\\d+)(?:st|nd|rd|th)?(?:\\s+(?:result|item|option))?").matcher(command);if(numbered.matches()){GestureAccessibilityService service=GestureAccessibilityService.getInstance();int index=Integer.parseInt(numbered.group(1));boolean ok=service!=null&&service.clickVisibleIndex(index);say(ok?"Done.":"I couldn't activate that visible item.");return;}if(c.startsWith("open "))if(openByName(command.substring(5).trim()))return;if(hasAiCore()){int priority=parsePriority(c);String goal=stripPriorityPrefix(command,c);String id=taskManager.submit(goal,priority);if(id.isEmpty())say("I couldn't add that task to NOVA's task manager.");else status("TASK "+id+" • ACCEPTED • P"+priority);return;}say("I can do built-in tablet tasks now. Configure an AI endpoint for open-ended reasoning and multi-step planning.");}catch(Exception e){Log.e(TAG,"COMMAND ERROR",e);say("I couldn't complete that action. Check that the required Android permission is enabled.");}}
    private int parsePriority(String c){if(c.startsWith("urgent ")||c.startsWith("critical ")||c.startsWith("high priority "))return NovaTaskManager.PRIORITY_HIGH;if(c.startsWith("low priority ")||c.startsWith("when you can ")||c.startsWith("later "))return NovaTaskManager.PRIORITY_LOW;return NovaTaskManager.PRIORITY_NORMAL;} private String stripPriorityPrefix(String original,String lower){String[] prefixes={"urgent ","critical ","high priority ","low priority ","when you can ","later "};for(String prefix:prefixes)if(lower.startsWith(prefix))return original.substring(prefix.length()).trim();return original.trim();}
    private void executeLocal(String type,String success){boolean ok=actions.execute(type,"");say(ok?success:"I couldn't perform that action. Check the required Android permission.");}
    private boolean handleMemory(String c,String original){if(c.equals("forget everything")||c.equals("clear memory")||c.equals("delete my memory")){memory.clear();context.getSharedPreferences("nova_user_memory",Context.MODE_PRIVATE).edit().clear().apply();taskManager.cancelAll();say("Local NOVA memory has been cleared.");return true;}if(c.startsWith("remember ")){String note=original.substring(9).trim();if(!note.isEmpty()){int as=note.toLowerCase(Locale.ROOT).indexOf(" as ");if(as>0&&as+4<note.length())memory.rememberFact(note.substring(as+4).trim(),note.substring(0,as).trim());else{context.getSharedPreferences("nova_user_memory",Context.MODE_PRIVATE).edit().putString("note",note).apply();memory.rememberFact("note",note);}say("I'll remember that locally on this tablet.");return true;}}if(containsAny(c,"what do you remember","what do you know about me")){String note=memory.factsSummary();if(note.equals("No saved facts."))note=context.getSharedPreferences("nova_user_memory",Context.MODE_PRIVATE).getString("note",note);say(note);return true;}return false;}
    private boolean openByName(String name){if(name.isEmpty())return false;if(name.toLowerCase(Locale.ROOT).contains("youtube"))return actions.execute("open_app","YouTube");android.content.pm.ResolveInfo info=apps.resolve(name);Intent launchIntent=apps.launchIntent(info);if(launchIntent!=null){launch(launchIntent);say("Opening "+info.loadLabel(context.getPackageManager())+".");return true;}return false;}
    private void search(String query){status("WEB RESEARCH • "+query);web.search(query,new NovaWebTool.Callback(){public void onResult(String text){say(text);}public void onError(String error){Log.w(TAG,"Web search failed: "+error);say("Web search failed.");}});}
    private String readScreen(){GestureAccessibilityService service=GestureAccessibilityService.getInstance();return service==null?"Accessibility service is not connected.":service.getVisibleTextSummary();} private String getUiSnapshot(){GestureAccessibilityService service=GestureAccessibilityService.getInstance();return service==null?"Accessibility service is not connected.":service.getUiSnapshot();}
    private void launch(Intent intent){try{context.startActivity(intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}catch(Exception e){Log.e(TAG,"Launch failed",e);}} private void say(String text){if(listener!=null)listener.onStatus(text);if(tts!=null&&text!=null&&!text.trim().isEmpty())tts.speak(text,TextToSpeech.QUEUE_FLUSH,null,"NOVA");} private void status(String text){if(listener!=null)listener.onStatus(text);} private boolean containsAny(String value,String...options){for(String option:options)if(value.equals(option)||value.contains(option))return true;return false;}
    public void shutdown(){if(tts!=null){tts.stop();tts.shutdown();}taskManager.shutdown();brain.shutdown();web.shutdown();aiProbe.shutdown();probeExecutor.shutdownNow();} public void destroy(){shutdown();}
}
